<?php
require __DIR__.'/config.php'; require __DIR__.'/database_upgrade.php'; header('Content-Type: application/json');
try{$p=db();apply_database_upgrade($p);$token=$_SESSION['visitor_token']??=bin2hex(random_bytes(16));$uid=user()['id']??null;if($_SERVER['REQUEST_METHOD']==='GET'){$q=$p->prepare('SELECT sender,message,created_at FROM support_messages WHERE '.($uid?'user_id=?':'visitor_token=?').' ORDER BY id DESC LIMIT 30');$q->execute([$uid?:$token]);echo json_encode(['ok'=>true,'messages'=>array_reverse($q->fetchAll())]);exit;}$text=trim($_POST['message']??'');if($text===''||mb_strlen($text)>500)throw new RuntimeException('Please enter a shorter message.');$p->prepare('INSERT INTO support_messages(user_id,visitor_token,sender,message)VALUES(?,?,"user",?)')->execute([$uid,$token,$text]);$q=strtolower($text);$reply=str_contains($q,'inquir')?'You can review inquiries from your dashboard. The business owner receives a notification when you send one.':(str_contains($q,'product')?'Open a business profile to see its available products and services.':(str_contains($q,'search')||str_contains($q,'find')?'Use Directory search with a category or Davao area such as Buhangin, Agdao, or Matina.':'I can help you discover Davao businesses, view services, save favorites, and send inquiries. What are you looking for?'));$p->prepare('INSERT INTO support_messages(user_id,visitor_token,sender,message)VALUES(?,?,"bot",?)')->execute([$uid,$token,$reply]);echo json_encode(['ok'=>true,'reply'=>$reply,'time'=>date('M j, g:i A')]);}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'reply'=>'We could not send that message. Please try again.']);}
